export function kofListAdd(list, value) {
    list.push(value);
}

export function kofListGet(list, index) {
    if (index < 0 || index >= list.length) {
        throw new Error("Index out of bounds: " + index + " (size " + list.length + ")");
    }
    return list[index];
}

export function kofListSize(list) {
    return list.length;
}
