    if (typeof setInterval === 'function') {
        return "n" + String(setInterval(() => kofTimeRunJob(fn), ms));
    }
    const id = "c" + (++kofTimeSeq.value);
    kofTimeJobs.set(id, { ms: ms, run: () => kofTimeRunJob(fn), next: Date.now() + ms });
